using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckFishing.Editor {
public static class FishingNetAuthoring {
 const string Folder="TruckFishing";static readonly List<Vector3> vertices=new List<Vector3>();static readonly List<Vector2> uv=new List<Vector2>();static readonly List<int> triangles=new List<int>();
 public static GameObject Create(){var root=new GameObject("Finished oval fishing net");var rim=SportsEventAuthoring.Mat(Folder,"Net brushed metal hoop",new Color(.7f,.75f,.72f),.6f);rim.SetFloat("_Metallic",.7f);var rope=SportsEventAuthoring.Mat(Folder,"Natural woven net rope",new Color(.78f,.67f,.42f),.08f);var wood=SportsEventAuthoring.Mat(Folder,"Fishing net wooden handle",new Color(.72f,.49f,.24f),.18f);wood.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/RoadPropsPack/Textures/T_WoodBox_AlbedoTransparency.png");Reset();var hoop=new Vector3[65];for(int i=0;i<hoop.Length;i++){float a=i*Mathf.PI*2/(hoop.Length-1);hoop[i]=new Vector3(Mathf.Cos(a)*1.1f,0,Mathf.Sin(a)*.65f);}Tube(hoop,.055f,10);Part(root.transform,"Rounded oval solid hoop","Oval Hoop",rim);Reset();for(int direction=-1;direction<=1;direction+=2)for(int line=0;line<24;line++){var points=new Vector3[15];for(int i=0;i<points.Length;i++){float t=i/(float)(points.Length-1),phi=t*1.48f,angle=line*Mathf.PI*2/24+direction*phi*2.8f;points[i]=new Vector3(Mathf.Cos(angle)*1.055f*Mathf.Cos(phi),-.52f*Mathf.Sin(phi),Mathf.Sin(angle)*.605f*Mathf.Cos(phi));}Tube(points,.014f,5);}var bag=Part(root.transform,"Net bag","Diamond Woven Bag",rope);bag.localPosition=Vector3.zero;Reset();Tube(new[]{new Vector3(0,.015f,-.62f),new Vector3(0,.65f,-3.8f)},.055f,12);Part(root.transform,"Hardwood handle","Wooden Handle",wood);Reset();var binding=new Vector3[97];for(int i=0;i<binding.Length;i++){float t=i/(float)(binding.Length-1),a=t*Mathf.PI*16;binding[i]=new Vector3(Mathf.Cos(a)*.082f,Mathf.Sin(a)*.082f+.035f,-.57f-t*.28f);}Tube(binding,.018f,5);Part(root.transform,"Visible rope hoop binding","Hoop Binding",rope);var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/"+Folder+"/Prefabs/Fishing Net.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static void Reset(){vertices.Clear();uv.Clear();triangles.Clear();}
 static void Tube(Vector3[] path,float radius,int sides){int offset=vertices.Count;for(int i=0;i<path.Length;i++){var tangent=(path[Mathf.Min(path.Length-1,i+1)]-path[Mathf.Max(0,i-1)]).normalized;var side=Vector3.Cross(tangent,Mathf.Abs(tangent.y)>.9f?Vector3.forward:Vector3.up).normalized;var up=Vector3.Cross(side,tangent).normalized;for(int j=0;j<=sides;j++){float a=j*Mathf.PI*2/sides;vertices.Add(path[i]+(side*Mathf.Cos(a)+up*Mathf.Sin(a))*radius);uv.Add(new Vector2(j/(float)sides,i*.15f));if(i==0||j==sides)continue;int k=offset+i*(sides+1)+j;triangles.AddRange(new[]{k,k+1,k-sides-1,k+1,k-sides,k-sides-1});}}}
 static Transform Part(Transform root,string name,string filename,Material material){var mesh=new Mesh{name=filename};mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path="Assets/"+Folder+"/Models/"+filename+".asset";var stored=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(stored==null){AssetDatabase.CreateAsset(mesh,path);stored=mesh;}else{stored.Clear();stored.indexFormat=mesh.indexFormat;stored.vertices=mesh.vertices;stored.normals=mesh.normals;stored.uv=mesh.uv;stored.triangles=mesh.triangles;stored.RecalculateBounds();stored.UploadMeshData(false);EditorUtility.SetDirty(stored);UnityEngine.Object.DestroyImmediate(mesh);}var g=new GameObject(name);g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=stored;g.AddComponent<MeshRenderer>().sharedMaterial=material;return g.transform;}
}
}
